  void _finishRun() {
    _disarmRunWatchdog();
    _state._isStreaming = false;
    _state._streamingMessage = null;
    _state._pendingToolCalls.clear();
    _activeRun?.completer.complete();
    _activeRun = null;
  }

  /// Reduce internal state for a loop event, then await listeners.
