String _humanize(Duration d) {
  if (d.inMilliseconds != 0 && d.inMilliseconds % 1000 != 0) {
    final tenths = (d.inMilliseconds / 100).round() / 10;
    return tenths == tenths.roundToDouble()
        ? '${tenths.round()}s'
        : '${tenths}s';
  }
  return '${d.inSeconds}s';
}

