/// bookkeeping.
Future<bool> _afterTransientFailure(
  AssistantMessageEventStream out,
  Model model,
  _TransientFailure failure,
  _DriveState state,
  CancelToken? cancelToken,
  _ResumeState resume,
  Duration delay,
  int maxAttempts,
) async {
  final error = failure.error;
  state.lastFailure = error;
