  void _touchRunWatchdog(AgentEvent event) {
    if (runIdleTimeout == Duration.zero) return;
    if (event is AgentEndEvent || event is AgentSettledEvent) {
      _disarmRunWatchdog();
      return;
    }
    if (_state._pendingToolCalls.isEmpty) {
      _armRunWatchdog();
    } else {
      _disarmRunWatchdog();
    }
